if($path==='admin' || $path==='login'){
    // Fake credentials are never verified, persisted, or forwarded to Google.
    if(!in_array($method,['GET','POST'],true)){
        header('Allow: GET, POST');http_response_code(405);exit;
    }
    $submitted=$method==='POST';
    // Capture submitted username/email and server-observed IP; never read or log passwords.
    $username=substr((string)($_POST['username']??''),0,254);
    $event=[
        'timestamp'=>gmdate('c'),
        'route'=>'/'.$path,
        'event'=>$submitted?'failed_login':'page_view',
        'ip'=>substr((string)($_SERVER['REMOTE_ADDR']??''),0,45),
        'user_agent'=>substr((string)($_SERVER['HTTP_USER_AGENT']??''),0,300),
        'username'=>$submitted?$username:null,
    ];
    $logfile=__DIR__.'/storage/honeypot.jsonl';
    $record=json_encode($event,JSON_INVALID_UTF8_SUBSTITUTE|JSON_UNESCAPED_SLASHES);
    if($record!==false && file_put_contents($logfile,$record."\n",FILE_APPEND|LOCK_EX)===false){
        error_log('Honeypot log write failed');
    }
    header('Cache-Control: no-store, private');
    header('X-Robots-Tag: noindex, nofollow');
    header('X-Frame-Options: DENY');
    header('X-Content-Type-Options: nosniff');
    header('Referrer-Policy: no-referrer');
    header("Content-Security-Policy: default-src 'none'; style-src 'unsafe-inline'; form-action 'self'; base-uri 'none'");
    header('Content-Type: text/html; charset=utf-8');
    http_response_code(200);
    $error=$submitted?'<p class="error" role="alert">Wrong username / password</p>':'';
    echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Administrator Login</title><style>*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;background:#f3f4f6;color:#1f2937;font:16px Arial,sans-serif;padding:24px}.panel{width:min(100%,390px);background:#fff;border:1px solid #d1d5db;border-radius:7px;padding:32px;box-shadow:0 6px 24px #0000000b}h1{font-size:23px;margin:0 0 8px}.hint{color:#6b7280;font-size:14px;margin-bottom:24px}label{display:block;font-weight:600;font-size:14px;margin:15px 0 7px}input{width:100%;padding:12px;border:1px solid #9ca3af;border-radius:4px;font:inherit}button{margin-top:24px;width:100%;padding:12px;border:0;border-radius:4px;background:#2563eb;color:#fff;font-weight:700;font-size:15px;cursor:pointer}.error{color:#b91c1c;background:#fef2f2;border:1px solid #fecaca;padding:11px;font-size:14px;border-radius:4px}</style></head><body><main class="panel"><h1>Administrator Login</h1><p class="hint">Sign in to continue.</p>'.$error.'<form method="post" action=""><label for="username">Username or email</label><input id="username" name="username" autocomplete="off" maxlength="254" required><label for="password">Password</label><input id="password" name="password" type="password" autocomplete="off" required><button type="submit">Log In</button></form></main></body></html>';
    exit;
}
