if($path==='feed.xml'||$path==='sitemap.xml'){$q=db()->query("SELECT title,slug,summary,body,publish_at,updated_at FROM posts WHERE status='published' AND publish_at<=NOW() ORDER BY publish_at DESC LIMIT 100")->fetchAll();header('Content-Type: application/xml; charset=utf-8');$x=fn($s)=>htmlspecialchars((string)$s,ENT_XML1|ENT_QUOTES,'UTF-8');if($path==='feed.xml'){echo '<?xml version="1.0" encoding="UTF-8"?><rss version="2.0"><channel><title>'.$x(setting('site_title')).'</title><link>'.$x(url()).'</link><description>Latest writing</description>';foreach($q as $p)echo '<item><title>'.$x($p['title']).'</title><link>'.$x(url('post/'.$p['slug'])).'</link><guid>'.$x(url('post/'.$p['slug'])).'</guid><pubDate>'.gmdate(DATE_RSS,strtotime($p['publish_at'])).'</pubDate><description>'.$x($p['summary']).'</description></item>';echo '</channel></rss>';}else{echo '<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"><url><loc>'.$x(url()).'</loc></url>';foreach($q as $p)echo '<url><loc>'.$x(url('post/'.$p['slug'])).'</loc></url>';echo '<url><loc>'.$x(url('about')).'</loc></url></urlset>';}exit;}
if(str_starts_with($path,'post/')){$slug=substr($path,5);$q=db()->prepare("SELECT * FROM posts WHERE slug=? AND status='published' AND publish_at<=NOW()");$q->execute([$slug]);$p=$q->fetch();if(!$p){http_response_code(404);layout('Page not found','<section class="hero notfound"><p class="eyebrow">404 / PAGE NOT FOUND</p><h1>Post not found.</h1><a class="button" href="'.h(url()).'">BACK TO ARTICLES ↗</a></section>');exit;}$html=video_and_pdfs($p['body']);$words=str_word_count(strip_tags($html));$toc='';preg_match_all('~<h([23])(?: id="([^"]+)")?>(.*?)</h[23]>~s',$html,$matches,PREG_SET_ORDER);if($matches){$toc='<aside class="toc"><strong>ON THIS PAGE</strong><ul>';foreach($matches as $i=>$m){$id='section-'.$i;$html=preg_replace('~'.preg_quote($m[0],'~').'~','<h'.$m[1].' id="'.$id.'">'.$m[3].'</h'.$m[1].'>',$html,1);$toc.='<li><a href="#'.$id.'">'.strip_tags($m[3]).'</a></li>';}$toc.='</ul></aside>';}$body='<article class="article"><p class="eyebrow">'.h(date('M j, Y',strtotime($p['publish_at']))).' · '.max(1,(int)ceil($words/220)).' MIN READ</p><h1>'.h($p['title']).'</h1>'.$toc.$html.'</article>';layout($p['title'],$body,false,$p['summary']);exit;}
if($path===''){ $posts=db()->query("SELECT title,slug,summary,publish_at FROM posts WHERE status='published' AND publish_at<=NOW() ORDER BY publish_at DESC LIMIT 100")->fetchAll();$body='<section class="hero"><p class="eyebrow">INDEPENDENT THINKING / WRITING</p><h1>'.h(setting('hero_headline','Less noise.')).'<br><em>'.h(setting('hero_accent','More signal.')).'</em></h1><p>'.nl2br(h(setting('hero_subtitle','Ideas worth thinking about.'))).'</p></section><div class="sectionhead"><strong>LATEST WRITING</strong><span>'.date('Y').' / ARCHIVE</span></div>';foreach($posts as $i=>$p){$body.='<a class="postrow" href="'.h(url('post/'.$p['slug'])).'"><b class="index">'.sprintf('%02d',$i+1).'</b><div><small>'.h(strtoupper(date('M j, Y',strtotime($p['publish_at'])))).'</small><h2>'.h($p['title']).'</h2><p>'.h($p['summary']).'</p></div><span>↗</span></a>';}if(!$posts)$body.='<p>First post coming soon.</p>';layout('Home',$body);exit;}
http_response_code(404);layout('Page not found','<section class="hero notfound"><p class="eyebrow">404 / PAGE NOT FOUND</p><h1>Wrong turn.<br><em>Try again.</em></h1><p>That page does not exist or has moved.</p><a class="button" href="'.h(url()).'">BACK TO ARTICLES ↗</a></section>');
